\label{def4} Let $(X,\Vert .,.,.\Vert )$ be an $S$-normed space.

\begin{enumerate}
\item A sequence $\{x_{n}\}$ in $X$ converges to $x$ if and only if 
\begin{equation*}
\underset{n\rightarrow \infty }{\lim }\Vert 0,x_{n}-x,x-x_{n}\Vert =0.
\end{equation*}
That is, for each $\varepsilon >0$ there exists $n_{0}\in


\mathbb{N}

$ such that 
\begin{equation*}
\Vert 0,x_{n}-x,x-x_{n}\Vert <\varepsilon \text{,}
\end{equation*} 
for all $n\geq n_{0}$.

\item A sequence $\{x_{n}\}$ in $X$ is called a Cauchy sequence if
\begin{equation*}
\underset{n,m,l\rightarrow \infty }{\lim }\Vert
x_{n}-x_{m},x_{m}-x_{l},x_{l}-x_{n}\Vert =0\text{.}
\end{equation*} 
That is, for each $\varepsilon >0$ there exists $n_{0}\in


\mathbb{N}

$ such that 
\begin{equation*}
\Vert x_{n}-x_{m},x_{m}-x_{l},x_{l}-x_{n}\Vert <\varepsilon \text{,}
\end{equation*} 
for all $n,m,l\geq n_{0}$.

\item An $S$-normed space is called complete if each Cauchy sequence in $X$
converges in $X$.

\item A complete $S$-normed space is called an $S$-Banach space.
\end{enumerate}

Let the sequence $\{x_{n}\}$ in $X$ be convergent to $x$. For each $ 
\varepsilon >0$, there exists $n_{0}\in


\mathbb{N}

$ such that 
\begin{equation*}
\Vert 0,x_{n}-x,x-x_{n}\Vert <\frac{\varepsilon }{3}\text{,}
\end{equation*} 
for all $n\geq n_{0}$. We now show that for each $\varepsilon >0$ there
exists $n_{0}\in


\mathbb{N}

$ such that 
\begin{equation*}
\Vert x_{n}-x_{m},x_{m}-x_{l},x_{l}-x_{n}\Vert <\varepsilon \text{,}
\end{equation*} 
for all $n,m,l\geq n_{0}$. Using the condition $(\mathbf{NS3})$, we obtain 
\begin{eqnarray*}
\Vert x_{n}-x_{m},x_{m}-x_{l},x_{l}-x_{n}\Vert &=&\Vert
x_{n}-x+x-x_{m},x_{m}-x+x-x_{l},x_{l}-x+x-x_{n}\Vert \\
&\leq &\Vert 0,x_{n}-x,x-x_{n}\Vert +\Vert 0,x_{m}-x,x-x_{m}\Vert \\
&&+\Vert 0,x_{l}-x,x-x_{l}\Vert \\
&<&\frac{\varepsilon }{3}+\frac{\varepsilon }{3}+\frac{\varepsilon }{3} 
=\varepsilon \text{.}
\end{eqnarray*} 
Consequently, the sequence $\{x_{n}\}$ in $X$ is a Cauchy sequence.

\label{exm5} Let $X=(0,1)\subset


\mathbb{R}

$ and the function $\Vert .,.,.\Vert :X\times X\times X\rightarrow


\mathbb{R}

$ be an $S$-norm generated by the usual norm on $X$. If we consider the
sequence $\{x_{n}\}=\left\{ \dfrac{1}{n}\right\} $ on $X$, then this
sequence is a Cauchy sequence, but it is not a convergent sequence on $X$.

Now we show that the sequence is a Cauchy sequence. For $x_{n}$, $x_{m}$, $ 
x_{l}\in X$, we obtain 
\begin{eqnarray*}
\underset{n,m,l\rightarrow \infty }{\lim }\Vert
x_{n}-x_{m},x_{m}-x_{l},x_{l}-x_{n}\Vert &=&\underset{n,m,l\rightarrow
\infty }{\lim }\left\Vert \frac{1}{n}-\frac{1}{m},\frac{1}{m}-\frac{1}{l}, 
\frac{1}{l}-\frac{1}{n}\right\Vert \\
&=&\underset{n,m,l\rightarrow \infty }{\lim }\left( \left\vert \frac{1}{n}- 
\frac{1}{m}\right\vert +\left\vert \frac{1}{m}-\frac{1}{l}\right\vert
+\left\vert \frac{1}{l}-\frac{1}{n}\right\vert \right) =0\text{.}
\end{eqnarray*} 
The sequence is convergent to $0$ as follows: 
\begin{equation*}
\underset{n\rightarrow \infty }{\lim }\Vert 0,x_{n}-x,x-x_{n}\Vert =\underset 
{n\rightarrow \infty }{\lim }\left\Vert 0,\frac{1}{n}-0,0-\frac{1}{n} 
\right\Vert =0\text{,}
\end{equation*} 
for all $x_{n}\in X$. But $0\notin X$. Consequently, the sequence is not
convergent on $X$.

\label{def8} Let $(X,\Vert .,.,.\Vert )$ be an $S$-normed space and $ 
A\subseteq X$. The $S$-diameter of $A$ is defined by 
\begin{equation*}
\delta ^{s}(A)=\sup \{\Vert 0,x-y,y-x\Vert :x,y\in A\}\text{.}
\end{equation*} 
If $A$ is bounded then we will write $\delta ^{s}(A)<\infty $.

\label{def9} Let $X$ be an $S$-Banach space, $A\subseteq X$ and $u\in X$.

\begin{enumerate}
\item The $S$-radius of $A$ relative to a given $u\in X$ is defined by 
\begin{equation*}
r_{u}^{s}(A)=\sup \{\Vert 0,u-x,x-u\Vert :x\in A\}\text{.}
\end{equation*}

\item The $S$-Chebyshev radius of $A$ is defined by 
\begin{equation*}
r^{s}(A)=\inf \{r_{u}^{s}(A):u\in A\}\text{.}
\end{equation*}

\item The $S$-Chebyshev centre of $A$ is defined by 
\begin{equation*}
C^{s}(A)=\{u\in A:r_{u}^{s}(A)=r^{s}(A)\}\text{.}
\end{equation*}
\end{enumerate}

\label{def12} Let $(X,\Vert .,.,.\Vert )$ be an $S$-Banach space and $T$ be
a self-mapping of $X$. We define 
\begin{equation*}
\begin{array}{r}
(\mathbf{NS25})\text{ \ \ }\Vert 0,Tx-Ty,Ty-Tx\Vert <\max \{\Vert
0,x-y,y-x\Vert ,\Vert 0,Tx-x,x-Tx\Vert , \\
\Vert 0,Ty-y,y-Ty\Vert ,\Vert 0,Ty-x,x-Ty\Vert ,\Vert 0,Tx-y,y-Tx\Vert \} 
\text{,} 
\end{array} 
\end{equation*} 
for each $x,y\in X$, $x\neq y$.

\cite{smulian} \label{lem1} Let $X$ be a Banach space. Then $X$ is reflexive
if and only if for any decreasing sequence $\{K_{n}\}$ of nonempty, bounded,
closed and convex subsets of $X$, 
\begin{equation*}
\bigcap\limits_{n=1}^{\infty }K_{n}\neq \emptyset \text{.}
\end{equation*}

\label{lem4} Let $X$ be an $S$-Banach space. Then $X$ is reflexive if and
only if for any decreasing sequence $\{K_{n}\}$ of nonempty, bounded, closed
and convex subsets of $X$, 
\begin{equation*}
\bigcap\limits_{n=1}^{\infty }K_{n}\neq \emptyset \text{.}
\end{equation*}

At first, we show that the existence of the fixed point. Let $\mathcal{A}$
be the family of every nonempty, closed and convex subsets of $A$. Also we
assume that if $F\in $ $\mathcal{A}$ then $TF\subseteq F$. The family $ 
\mathcal{A}$ is nonempty since $A\in $ $\mathcal{A}$. We can partially order
$\mathcal{A}$ by set inclusion, that is, if $F_{1}\subseteq F_{2}$ then $ 
F_{1}\leq F_{2}$.

In $\mathcal{A}$, if we define a decreasing net of subsets 
\begin{equation*}
S=\{F_{i}:F_{i}\in \text{$\mathcal{A}$},i\in I\}\text{,}
\end{equation*} 
then by reflexivity, this net $S$ has nonempty intersection. Because it is a
decreasing net of nonempty, closed, bounded and convex subsets of $X$. If we
put $F_{0}=\bigcap\limits_{i\in I}F_{i}$ we have that $F_{0}$ is in $ 
\mathcal{A}$ and is a lower bound of $S$.

Using Zorn's Lemma, there is a minimal element, denoted by $F$, in $\mathcal{ 
A}$ as $S$ is any arbitrary decreasing net in $\mathcal{A}$. We see that
this $F$ is a singleton.

Assume that $\delta ^{s}(F)\neq \emptyset $. Since $F$ is nonempty, closed
and convex, $C^{s}(F)$ is a nonempty, closed and convex subset of $F$. We
have that 
\begin{equation*}
r^{s}(F)<\delta ^{s}(F)\text{,}
\end{equation*} 
\begin{equation*}
\delta ^{s}(C^{s}(F))\leq r^{s}(F)<\delta ^{s}(F)
\end{equation*} 
and so $C^{s}(F)$ is a proper subset of $F$.

Let $(F_{m})_{m\in


\mathbb{N}

}$ be an increasing sequence of subsets of $F$, defined by 
\begin{equation*}
F_{1}=C^{s}(F)\text{ and }F_{m+1}=conv(F_{m}\cup TF_{m})\text{,}
\end{equation*} 
for all $m\in


\mathbb{N}

$. If we denote the $S$-diameters of these sets $F_{k}$ by $\delta
_{k}^{s}=\delta ^{s}(F_{k})$, we show that 
\begin{equation*}
\delta _{k}^{s}\leq r^{s}(F)\text{,}
\end{equation*} 
for all $k\in


\mathbb{N}

$.

Using the $(PMI)$, we obtain

\begin{enumerate}
\item For $k=1$, 
\begin{equation*}
\delta _{1}^{s}=\delta ^{s}(F_{1})=\delta ^{s}(C^{s}(F))\leq r^{s}(F)\text{.}
\end{equation*}

\item If $\delta _{k}^{s}\leq r^{s}(F)$ for every $k=1,...,m$ then $\delta
_{m+1}^{s}\leq r^{s}(F)$.
\end{enumerate}

We note that 
\begin{equation*}
\delta _{m+1}^{s}=\delta ^{s}(F_{m+1})=\delta ^{s}(conv(F_{m}\cup
TF_{m}))=\delta ^{s}(F_{m}\cup TF_{m})\text{.}
\end{equation*} 
By the definition of $S$-diameter, for any given $\varepsilon >0$ there are $ 
x^{\prime }$ and $y^{\prime }$ in $F_{m}\cup T(F_{m})$ satisfying 
\begin{equation*}
\delta _{m+1}^{s}-\varepsilon <\Vert 0,x^{\prime }-y^{\prime },y^{\prime
}-x^{\prime }\Vert \leq \delta _{m+1}^{s}\text{.}
\end{equation*} 
We obtain the following three cases for $x^{\prime }$, $y^{\prime }$:

\begin{enumerate}
\item $x^{\prime }$, $y^{\prime }\in F_{m}$ or

\item $x^{\prime }\in F_{m}$ and $y^{\prime }\in TF_{m}$ or

\item $x^{\prime }$, $y^{\prime }\in TF_{m}$.
\end{enumerate}

Redefining $x^{\prime }$ and $y^{\prime }$ as follows:

\begin{enumerate}
\item $x^{\prime }=x$ and $y^{\prime }=y$ with $x,y\in F_{m}$,

\item $x^{\prime }=x$ and $y^{\prime }=Ty$ with $x,y\in F_{m}$,

\item $x^{\prime }=Tx$ and $y^{\prime }=Ty$ with $x,y\in F_{m}$.
\end{enumerate}

We show that in any case 
\begin{equation*}
\delta _{m+1}^{s}-\varepsilon <r^{s}(F)\text{.}
\end{equation*}

\textbf{Case 1}. By the definition of $\delta _{m}^{s}$ and the induction
hypothesis, we obtain 
\begin{equation}
\delta _{m+1}^{s}-\varepsilon <\Vert 0,x-y,y-x\Vert \leq \delta
_{m+1}^{s}\leq r^{s}(F)  \label{eqn1}
\end{equation} 
and so $\delta _{m+1}^{s}-\varepsilon <r^{s}(F)$.

\textbf{Case 2}. We obtain 
\begin{equation*}
\delta _{m+1}^{s}-\varepsilon <\Vert 0,x-Ty,Ty-x\Vert
\end{equation*} 
with $x$, $y\in F_{m}$. Then by the definition of $F_{m}$, we have $x,y\in
conv(F_{m-1}\cup TF_{m-1})$ and so there is a finite index set $I$ such that
$x=\sum\limits_{i\in I}\alpha _{i}x_{i}$, with $\sum\limits_{i\in I}\alpha
_{i}=1$, $\alpha _{i}\geq 0$ and $x_{i}\in F_{m-1}\cup TF_{m-1}$ for any $ 
i\in I$. We can separate the set $I$ in two disjoint subsets, $I=I_{1}\cup
I_{2}$, such that if $i\in I_{1}$ then $x_{i}\in F_{m-1}$ and if $i\in I_{2}$
then $x_{i}\in TF_{m-1}$.

Now redefining $x_{i}$ as $x_{i}=Tx_{i}$ with $x_{i}\in F_{m-1}$, we obtain 
\begin{equation*}
x=\sum\limits_{i\in I_{1}}\alpha _{i}x_{i}+\sum\limits_{i\in I_{2}}\alpha
_{i}Tx_{i}\text{.}
\end{equation*} 
Substituting in $\Vert 0,x-Ty,Ty-x\Vert $, we get 
\begin{equation}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{i\in I_{1}}\alpha _{i}\Vert
0,x_{i}-Ty,Ty-x_{i}\Vert +\sum\limits_{i\in I_{2}}\alpha _{i}\Vert
0,Tx_{i}-Ty,Ty-Tx_{i}\Vert \text{.}  \label{eqn2}
\end{equation} 
Applying the condition $(\mathbf{NS25})$ to $\Vert
0,Tx_{i}-Ty,Ty-Tx_{i}\Vert $, we have 
\begin{equation}
\begin{array}{r}
\Vert 0,Tx_{i}-Ty,Ty-Tx_{i}\Vert <\max \{\Vert 0,x_{i}-y,y-x_{i}\Vert ,\Vert
0,x_{i}-Tx_{i},Tx_{i}-x_{i}\Vert , \\
\Vert 0,y-Ty,Ty-y\Vert ,\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert ,\Vert
0,Tx_{i}-y,y-Tx_{i}\Vert \}\text{.} 
\end{array}
\label{eqn3}
\end{equation} 
As $x_{i}\in F_{m-1}$, $Tx_{i},y\in F_{m}$, we have 
\begin{equation*}
\begin{array}{l}
\Vert 0,x_{i}-y,y-x_{i}\Vert \leq r^{s}(F), \\
\Vert 0,x_{i}-Tx_{i},Tx_{i}-x_{i}\Vert \leq r^{s}(F), \\
\Vert 0,Tx_{i}-y,y-Tx_{i}\Vert \leq r^{s}(F) 
\end{array} 
\end{equation*} 
and replacing in (\ref{eqn3}), we obtain 
\begin{equation*}
\Vert 0,Tx_{i}-Ty,Ty-Tx_{i}\Vert <\max \{r^{s}(F),\Vert 0,y-Ty,Ty-y\Vert
,\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert \}\text{.}
\end{equation*} 
Let us subdivide the index set $I_{2}$ in three disjoint subsets $ 
I_{2}=I_{2}^{1}\cup I_{2}^{2}\cup I_{2}^{3}$ such that 
\begin{equation*}
\begin{array}{l}
I_{2}^{1}=\{i\in I_{2}:\Vert 0,Tx_{i}-Ty,Ty-Tx_{i}\Vert <r^{s}(F)\}, \\
I_{2}^{2}=\{i\in I_{2}:\Vert 0,Tx_{i}-Ty,Ty-Tx_{i}\Vert <\Vert
0,x_{i}-Ty,Ty-x_{i}\Vert \}, \\
I_{2}^{3}=\{i\in I_{2}:\Vert 0,Tx_{i}-Ty,Ty-Tx_{i}\Vert <\Vert
0,y-Ty,Ty-y\Vert \}. 
\end{array} 
\end{equation*} 
Then using (\ref{eqn2}), we have
\begin{equation}
\begin{array}{c}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{i\in I_{1}\cup I_{2}^{2}}\alpha
_{i}\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert +\sum\limits_{i\in I_{2}^{1}}\alpha
_{i}r^{s}(F) \\
+\sum\limits_{i\in I_{2}^{3}}\alpha _{i}\Vert 0,y-Ty,Ty-y\Vert \text{.} 
\end{array}
\label{eqn4}
\end{equation} 
Redefining $I_{1}$, $I_{2}$ and $I_{3}$ 
\begin{equation}
\overline{I_{1}}=I_{1}\cup I_{2}^{2}\text{, }\overline{I_{2}}=I_{2}^{1}\text{
and }\overline{I_{3}}=I_{2}^{3}\text{.}  \label{eqn5}
\end{equation} 
Then we have $I=\overline{I_{1}}\cup \overline{I_{2}}\cup \overline{I_{3}}$,
with $\overline{I_{j}}\cap \overline{I_{k}}=\emptyset $. If $j\neq k$ and $ 
\sum\limits_{i\in I}\alpha _{i}=1$ then using (\ref{eqn4}), it becomes 
\begin{equation}
\begin{array}{c}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{i\in \overline{I_{1}}}\alpha
_{i}\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert +\sum\limits_{i\in \overline{I_{2}} 
}\alpha _{i}r^{s}(F) \\
+\sum\limits_{i\in \overline{I_{3}}}\alpha _{i}\Vert 0,y-Ty,Ty-y\Vert \text{. 
} 
\end{array}
\label{eqn6}
\end{equation} 
If $A_{0}=\sum\limits_{i\in \overline{I_{2}}}\alpha _{i}$ and $ 
B_{0}=\sum\limits_{i\in \overline{I_{3}}}\alpha _{i}$ with $ 
\sum\limits_{i\in \overline{I_{1}}}\alpha _{i}+A_{0}+B_{0}=1$. Using (\ref 
{eqn6}), we have 
\begin{equation}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{i\in \overline{I_{1}}}\alpha
_{i}\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert +A_{0}r^{s}(F)+B_{0}\Vert
0,y-Ty,Ty-y\Vert \text{.}  \label{eqn7}
\end{equation} 
For each $i\in \overline{I_{1}}$, $x_{i}\in F_{m-1}=conv(F_{m-2}\cup
TF_{m-2})$, there is a finite set $J_{i}$, such that
\begin{equation}
x_{i}=\sum\limits_{j\in J_{i}}\beta _{i}^{j}x_{i}^{j}\text{,}  \label{eqn8}
\end{equation} 
with $x_{i}^{j}\in F_{m-2}\cup TF_{m-2}$, $\beta _{i}^{j}\geq 0$ and $ 
\sum\limits_{j\in J_{i}}\beta _{i}^{j}=1$ for any $j\in J_{i}$. Let $ 
J_{i}=J_{i}^{1}\cup J_{i}^{2}$, with $J_{i}^{1}\cap J_{i}^{2}=\emptyset $
such that 
\begin{equation}
x_{i}=\sum\limits_{j\in J_{i}^{1}}\beta _{i}^{j}x_{i}^{j}+\sum\limits_{j\in
J_{i}^{2}}\beta _{i}^{j}Tx_{i}^{j}\text{.}  \label{eqn9}
\end{equation} 
For each $i\in \overline{I_{1}}$ we have 
\begin{equation}
\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert \leq \sum\limits_{j\in J_{i}^{1}}\beta
_{i}^{j}\Vert 0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert +\sum\limits_{j\in
J_{i}^{2}}\beta _{i}^{j}\Vert 0,Tx_{i}^{j}-Ty,Ty-Tx_{i}^{j}\Vert \text{.}
\label{eqn10}
\end{equation} 
Applying the condition $(\mathbf{NS25})$ to $\Vert
0,Tx_{i}^{j}-Ty,Ty-Tx_{i}^{j}\Vert $, we have 
\begin{equation}
\begin{array}{r}
\Vert 0,Tx_{i}^{j}-Ty,Ty-Tx_{i}^{j}\Vert <\max \{\Vert
0,x_{i}^{j}-y,y-x_{i}^{j}\Vert ,\Vert
0,Tx_{i}^{j}-x_{i}^{j},x_{i}^{j}-Tx_{i}^{j}\Vert , \\
\Vert 0,y-Ty,Ty-y\Vert ,\Vert 0,Tx_{i}^{j}-y,y-Tx_{i}^{j}\Vert ,\Vert
0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert \}\text{.} 
\end{array}
\label{eqn11}
\end{equation} 
Since $x_{i}^{j}\in F_{m-2}$ and $y\in F_{m}$, we have 
\begin{equation*}
\begin{array}{l}
\Vert 0,x_{i}^{j}-y,y-x_{i}^{j}\Vert \leq r^{s}(F), \\
\Vert 0,Tx_{i}^{j}-x_{i}^{j},x_{i}^{j}-Tx_{i}^{j}\Vert \leq r^{s}(F), \\
\Vert 0,Tx_{i}^{j}-y,y-Tx_{i}^{j}\Vert \leq r^{s}(F). 
\end{array} 
\end{equation*} 
By (\ref{eqn11}), we obtain 
\begin{equation*}
\Vert 0,Tx_{i}^{j}-Ty,Ty-Tx_{i}^{j}\Vert <\max \{r^{s}(F),\Vert
0,y-Ty,Ty-y\Vert ,\Vert 0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert \}\text{.}
\end{equation*} 
Let $J_{i}^{2}=J_{i}^{2_{1}}\cup J_{i}^{2_{2}}\cup J_{i}^{2_{3}}$ with $ 
J_{i}^{2_{k}}\cap J_{i}^{2_{p}}=\emptyset $ such that 
\begin{equation*}
\begin{array}{l}
J_{i}^{2_{1}}=\{j\in J_{i}^{2}:\Vert 0,Tx_{i}^{j}-Ty,Ty-Tx_{i}^{j}\Vert
<r^{s}(F)\}, \\
J_{i}^{2_{2}}=\{j\in J_{i}^{2}:\Vert 0,Tx_{i}^{j}-Ty,Ty-Tx_{i}^{j}\Vert
<\Vert 0,y-Ty,Ty-y\Vert \}, \\
J_{i}^{2_{3}}=\{j\in J_{i}^{2}:\Vert 0,Tx_{i}^{j}-Ty,Ty-Tx_{i}^{j}\Vert
<\Vert 0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert \}. 
\end{array} 
\end{equation*} 
Using (\ref{eqn10}), we obtain 
\begin{equation}
\begin{array}{c}
\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert \leq \sum\limits_{j\in J_{i}^{1}\cup
J_{i}^{2_{3}}}\beta _{i}^{j}\Vert 0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert
+\sum\limits_{i\in J_{i}^{2_{1}}}\beta _{i}^{j}r^{s}(F) \\
+\sum\limits_{i\in J_{i}^{2_{2}}}\beta _{i}^{j}\Vert 0,y-Ty,Ty-y\Vert . 
\end{array}
\label{eqn12}
\end{equation} 
Let us denote by 
\begin{equation*}
J_{1}^{i}=J_{i}^{1}\cup J_{i}^{2_{3}}\text{, }J_{2}^{i}=J_{i}^{2_{2}}\text{
and }J_{3}^{i}=J_{i}^{2_{1}}\text{.}
\end{equation*} 
Then using (\ref{eqn12}), we have 
\begin{equation}
\begin{array}{c}
\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert \leq \sum\limits_{j\in J_{1}^{i}}\beta
_{i}^{j}\Vert 0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert +\sum\limits_{i\in
J_{3}^{i}}\beta _{i}^{j}r^{s}(F) \\
+\sum\limits_{i\in J_{2}^{i}}\beta _{i}^{j}\Vert 0,y-Ty,Ty-y\Vert . 
\end{array}
\label{eqn13}
\end{equation} 
If $A_{i}=\sum\limits_{i\in J_{3}^{i}}\beta _{i}^{j}$ and $ 
B_{i}=\sum\limits_{i\in J_{2}^{i}}\beta _{i}^{j}$ with $\sum\limits_{j\in
J_{1}^{i}}\beta _{i}^{j}+A_{i}+B_{i}=1$. Using (\ref{eqn13}), we obtain 
\begin{equation}
\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert \leq \sum\limits_{j\in J_{1}^{i}}\beta
_{i}^{j}\Vert 0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert +A_{i}r^{s}(F)+B_{i}\Vert
0,y-Ty,Ty-y\Vert .  \label{eqn14}
\end{equation} 
Using (\ref{eqn7}) and $\Vert 0,x_{i}-Ty,Ty-x_{i}\Vert $ by (\ref{eqn14}),
we obtain 
\begin{equation*}
\begin{array}{c}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{i\in \overline{I_{1}}}\alpha
_{i}\sum\limits_{j\in J_{1}^{i}}\beta _{i}^{j}\Vert
0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert +\left[ \sum\limits_{i\in \overline{I_{1}} 
}\alpha _{i}A_{i}+A_{0}\right] r^{s}(F) \\
+\left[ \sum\limits_{i\in \overline{I_{1}}}\alpha _{i}B_{i}+B_{0}\right]
\Vert 0,y-Ty,Ty-y\Vert . 
\end{array} 
\end{equation*} 
Let $A_{1}=\sum\limits_{i\in \overline{I_{1}}}\alpha _{i}A_{i}$ and $ 
B_{1}=\sum\limits_{i\in \overline{I_{1}}}\alpha _{i}B_{i}$. Then we have 
\begin{equation}
\begin{array}{c}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{i\in \overline{I_{1}}}\alpha
_{i}\sum\limits_{j\in J_{1}^{i}}\beta _{i}^{j}\Vert
0,x_{i}^{j}-Ty,Ty-x_{i}^{j}\Vert +(A_{1}+A_{0})r^{s}(F) \\
+(B_{1}+B_{0})\Vert 0,y-Ty,Ty-y\Vert . 
\end{array}
\label{eqn15}
\end{equation} 
We note that 
\begin{equation*}
\sum\limits_{i\in \overline{I_{1}}}\alpha _{i}\sum\limits_{j\in
J_{1}^{i}}\beta _{i}^{j}+\sum\limits_{i\in \overline{I_{1}}}\alpha
_{i}A_{i}+A_{0}+\sum\limits_{i\in \overline{I_{1}}}\alpha _{i}B_{i}+B_{0}=1.
\end{equation*} 
Let us take $K=\underset{i\in \overline{I_{1}}}{\bigcup }\left( \underset{ 
j\in J_{1}^{i}}{\bigcup }j\right) $ and denote the scalars by $\xi _{k}$. To
each $k$ relative to the pair $(i,j)$, $x_{i}^{j}$ will be denoted by $x_{k}$ 
.

Using (\ref{eqn15}), we obtain 
\begin{equation*}
\begin{array}{c}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{k\in K}\xi _{k}\Vert
0,x_{k}-Ty,Ty-x_{k}\Vert +(A_{1}+A_{0})r^{s}(F) \\
+(B_{1}+B_{0})\Vert 0,y-Ty,Ty-y\Vert , 
\end{array} 
\end{equation*} 
where $\sum\limits_{k\in K}\xi _{k}+A_{1}+A_{0}+B_{1}+B_{0}=1$ and $x_{k}\in
F_{m-2}$.

Repeating this process which is done for $x_{k}$, we get 
\begin{equation}
\begin{array}{c}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{p\in P}\gamma _{p}\Vert
0,x_{p}-Ty,Ty-x_{p}\Vert +\sum\limits_{k=0}^{m-1}A_{k}r^{s}(F) \\
+\sum\limits_{k=0}^{m-1}B_{k}\Vert 0,y-Ty,Ty-y\Vert , 
\end{array}
\label{eqn16}
\end{equation} 
where $\sum\limits_{p\in P}\gamma
_{p}+\sum\limits_{i=0}^{m-1}(A_{i}+B_{i})=1 $ and $x_{p}\in F_{1}=C^{s}(F)$.

Hence $\Vert 0,x_{p}-Ty,Ty-x_{p}\Vert \leq r^{s}(F)$ and using (\ref{eqn16} 
), we obtain 
\begin{equation}
\Vert 0,x-Ty,Ty-x\Vert \leq \sum\limits_{k=0}^{m-1}B_{k}\Vert
0,y-Ty,Ty-y\Vert +\left( \sum\limits_{p\in P}\gamma
_{p}+\sum\limits_{k=0}^{m-1}A_{k}\right) r^{s}(F).  \label{eqn17}
\end{equation} 
Let us turn to $\Vert 0,y-Ty,Ty-y\Vert $. Since $y\in conv(F_{m-1}\cup
TF_{m-1})$, we have $y=\sum\limits_{i\in I}\alpha _{i}y_{i}$ with $ 
\sum\limits_{i\in I}\alpha _{i}=1$, $y_{i}\in F_{m-1}\cup TF_{m-1}$ and $ 
\alpha _{i}\geq 0$ for all $i\in I$. Let $I=I_{1}\cup I_{2}$ such that $ 
I_{1}\cap I_{2}=\emptyset $. If $i\in I_{1}$ then $y_{i}\in F_{m-1}$ and if $ 
i\in I_{2}$ then $y_{i}\in TF_{m-1}$. Let $y_{i}=Ty_{i}$. Then we can write 
\begin{equation*}
y=\sum\limits_{i\in I_{1}}\alpha _{i}y_{i}+\sum\limits_{i\in I_{2}}\alpha
_{i}Ty_{i},
\end{equation*} 
with $y_{i}\in F_{m-1}$.

Substituting in $\Vert 0,y-Ty,Ty-y\Vert $ we get 
\begin{equation}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{i\in I_{1}}\alpha _{i}\Vert
0,y_{i}-Ty,Ty-y_{i}\Vert +\sum\limits_{i\in I_{2}}\alpha _{i}\Vert
0,Ty_{i}-Ty,Ty-Ty_{i}\Vert .  \label{eqn18}
\end{equation} 
Using the condition $(\mathbf{NS}25)$, we obtain 
\begin{equation}
\begin{array}{r}
\Vert 0,Ty_{i}-Ty,Ty-Ty_{i}\Vert <\max \{\Vert 0,y_{i}-y,y-y_{i}\Vert ,\Vert
0,y_{i}-Ty_{i},Ty_{i}-y_{i}\Vert , \\
\Vert 0,y-Ty,Ty-y\Vert ,\Vert 0,y_{i}-Ty,Ty-y_{i}\Vert ,\Vert
0,Ty_{i}-y,y-Ty_{i}\Vert \}\text{.} 
\end{array}
\label{eqn19}
\end{equation} 
Since $y_{i}\in F_{m-1}$, $y\in F_{m}$, we have 
\begin{equation*}
\begin{array}{l}
\Vert 0,y_{i}-y,y-y_{i}\Vert \leq r^{s}(F), \\
\Vert 0,y_{i}-Ty_{i},Ty_{i}-y_{i}\Vert \leq r^{s}(F), \\
\Vert 0,Ty_{i}-y,y-Ty_{i}\Vert \leq r^{s}(F). 
\end{array} 
\end{equation*} 
Using (\ref{eqn19}), we obtain 
\begin{equation*}
\Vert 0,Ty_{i}-Ty,Ty-Ty_{i}\Vert <\max \{r^{s}(F),\Vert 0,y-Ty,Ty-y\Vert
,\Vert 0,y_{i}-Ty,Ty-y_{i}\Vert \}\text{.}
\end{equation*} 
Redefining the index set $I_{2}=I_{2}^{1}\cup I_{2}^{2}\cup I_{2}^{3}$ with 
\begin{equation*}
\begin{array}{l}
I_{2}^{1}=\{i\in I_{2}:\Vert 0,Ty_{i}-Ty,Ty-Ty_{i}\Vert <r^{s}(F)\}, \\
I_{2}^{2}=\{i\in I_{2}:\Vert 0,Ty_{i}-Ty,Ty-Ty_{i}\Vert <\Vert
0,y-Ty,Ty-y\Vert \}, \\
I_{2}^{3}=\{i\in I_{2}:\Vert 0,Ty_{i}-Ty,Ty-Ty_{i}\Vert <\Vert
0,y_{i}-Ty,Ty-y_{i}\Vert \}. 
\end{array} 
\end{equation*} 
Now using (\ref{eqn18}), we get
\begin{equation}
\begin{array}{c}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{i\in I_{1}\cup I_{2}^{3}}\alpha
_{i}\Vert 0,y_{i}-Ty,Ty-y_{i}\Vert +\sum\limits_{i\in I_{2}^{1}}\alpha
_{i}r^{s}(F) \\
+\sum\limits_{i\in I_{2}^{2}}\alpha _{i}\Vert 0,y-Ty,Ty-y\Vert . 
\end{array}
\label{eqn20}
\end{equation} 
We note that if $\sum\limits_{i\in I_{2}^{2}}\alpha _{i}=1$ then 
\begin{equation*}
\Vert 0,y-Ty,Ty-y\Vert \leq \Vert 0,Ty_{i}-Ty,Ty-Ty_{i}\Vert <\Vert
0,y-Ty,Ty-y\Vert ,
\end{equation*} 
which is a contradiction.

Then $\sum\limits_{i\in I_{2}^{2}}\alpha _{i}<1$ and using (\ref{eqn20}), we
obtain 
\begin{equation}
\begin{array}{c}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{i\in I_{1}\cup I_{2}^{3}}\dfrac{ 
\alpha _{i}}{1-\sum\limits_{i\in I_{2}^{2}}\alpha _{i}}\Vert
0,y_{i}-Ty,Ty-y_{i}\Vert \\
+\sum\limits_{i\in I_{2}^{1}}\dfrac{\alpha _{i}}{1-\sum\limits_{i\in
I_{2}^{2}}\alpha _{i}}r^{s}(F), 
\end{array}
\label{eqn21}
\end{equation} 
with $\sum\limits_{i\in I_{1}\cup I_{2}^{3}}\dfrac{\alpha _{i}}{ 
1-\sum\limits_{i\in I_{2}^{2}}\alpha _{i}}+\sum\limits_{i\in I_{2}^{1}} 
\dfrac{\alpha _{i}}{1-\sum\limits_{i\in I_{2}^{2}}\alpha _{i}}=1$.

Let $I_{1}=I_{1}\cup I_{2}^{3}$, $I_{2}=I_{2}^{1}$ and $\beta _{i}=\dfrac{ 
\alpha _{i}}{1-\sum\limits_{i\in I_{2}^{2}}\alpha _{i}}$. Using (\ref{eqn21} 
), we obtain 
\begin{equation}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{i\in I_{1}}\beta _{i}\Vert
0,y_{i}-Ty,Ty-y_{i}\Vert +\sum\limits_{i\in I_{2}}\beta _{i}r^{s}(F).
\label{eqn22}
\end{equation} 
If $A_{0}=\sum\limits_{i\in I_{2}}\beta _{i}$ then using (\ref{eqn22}), we
have 
\begin{equation}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{i\in I_{1}}\beta _{i}\Vert
0,y_{i}-Ty,Ty-y_{i}\Vert +A_{0}r^{s}(F),  \label{eqn23}
\end{equation} 
with $\sum\limits_{i\in I_{1}}\beta _{i}+A_{0}=1$ and $y_{i}\in
F_{m-1}=conv(F_{m-2}\cup TF_{m-2})$.

For each $i\in I_{1}$, 
\begin{equation*}
y_{i}=\sum\limits_{j\in J_{i}^{1}}\gamma _{i}^{j}y_{i}^{j}+\sum\limits_{j\in
J_{i}^{2}}\gamma _{i}^{j}Ty_{i}^{j},
\end{equation*} 
with $y_{i}^{j}\in F_{m-2}$ and $\sum\limits_{j\in J_{i}^{1}\cup
J_{i}^{2}}\gamma _{i}^{j}=1$. So we obtain 
\begin{equation}
\Vert 0,y_{i}-Ty,Ty-y_{i}\Vert \leq \sum\limits_{j\in J_{i}^{1}}\gamma
_{i}^{j}\Vert 0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert +\sum\limits_{j\in
J_{i}^{2}}\gamma _{i}^{j}\Vert 0,Ty_{i}^{j}-Ty,Ty-Ty_{i}^{j}\Vert .
\label{eqn24}
\end{equation} 
Using the condition $(\mathbf{NS25}),$ we have 
\begin{equation*}
\begin{array}{r}
\Vert 0,Ty_{i}^{j}-Ty,Ty-Ty_{i}^{j}\Vert <\max \{\Vert
0,y_{i}^{j}-y,y-y_{i}^{j}\Vert ,\Vert
0,Ty_{i}^{j}-y_{i}^{j},y_{i}^{j}-Ty_{i}^{j}\Vert , \\
\Vert 0,y-Ty,Ty-y\Vert ,\Vert 0,Ty_{i}^{j}-y,y-Ty_{i}^{j}\Vert ,\Vert
0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert \}\text{.} 
\end{array} 
\end{equation*} 
Since $y_{i}^{j}\in F_{m-2}$, $Ty_{i}^{j}\in F_{m-1}$ and $y\in F_{m}$, we
can write 
\begin{equation*}
\begin{array}{l}
\Vert 0,y_{i}^{j}-y,y-y_{i}^{j}\Vert \leq r^{s}(F), \\
\Vert 0,Ty_{i}^{j}-y_{i}^{j},y_{i}^{j}-Ty_{i}^{j}\Vert \leq r^{s}(F), \\
\Vert 0,Ty_{i}^{j}-y,y-Ty_{i}^{j}\Vert \leq r^{s}(F) 
\end{array} 
\end{equation*} 
and 
\begin{equation*}
\Vert 0,Ty_{i}^{j}-Ty,Ty-Ty_{i}^{j}\Vert <\max \{r^{s}(F),\Vert
0,y-Ty,Ty-y\Vert ,\Vert 0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert \}\text{.}
\end{equation*} 
Let $J_{i}^{2}$ be the union of the disjoint sets $J_{i}^{2}=J_{i}^{2_{1}} 
\cup J_{i}^{2_{2}}\cup J_{i}^{2_{3}}$ such that 
\begin{equation*}
\begin{array}{l}
J_{i}^{2_{1}}=\{j\in J_{i}^{2}:\Vert 0,Ty_{i}^{j}-Ty,Ty-Ty_{i}^{j}\Vert
<\Vert 0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert \}, \\
J_{i}^{2_{2}}=\{j\in J_{i}^{2}:\Vert 0,Ty_{i}^{j}-Ty,Ty-Ty_{i}^{j}\Vert
<r^{s}(F)\}, \\
J_{i}^{2_{3}}=\{j\in J_{i}^{2}:\Vert 0,Ty_{i}^{j}-Ty,Ty-Ty_{i}^{j}\Vert
<\Vert 0,y-Ty,Ty-y\Vert \}. 
\end{array} 
\end{equation*} 
Using (\ref{eqn24}), we obtain 
\begin{equation}
\begin{array}{c}
\Vert 0,y_{i}-Ty,Ty-y_{i}\Vert \leq \sum\limits_{j\in J_{i}^{1}\cup
J_{i}^{2_{1}}}\gamma _{i}^{j}\Vert 0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert
+\sum\limits_{j\in J_{i}^{2_{2}}}\gamma _{i}^{j}r^{s}(F) \\
+\sum\limits_{j\in J_{i}^{2_{3}}}\gamma _{i}^{j}\Vert 0,y-Ty,Ty-y\Vert . 
\end{array}
\label{eqn25}
\end{equation} 
Now redefine the index sets $J_{i}^{1}=J_{i}^{1}\cup J_{i}^{2_{1}}$, $ 
J_{i}^{2}=J_{i}^{2_{2}},$ $J_{i}^{3}=J_{i}^{2_{3}}$ and using (\ref{eqn25})
we can write 
\begin{equation*}
\begin{array}{c}
\Vert 0,y_{i}-Ty,Ty-y_{i}\Vert \leq \sum\limits_{j\in J_{i}^{1}}\gamma
_{i}^{j}\Vert 0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert +\sum\limits_{j\in
J_{i}^{2}}\gamma _{i}^{j}r^{s}(F) \\
+\sum\limits_{j\in J_{i}^{3}}\gamma _{i}^{j}\Vert 0,y-Ty,Ty-y\Vert , 
\end{array} 
\end{equation*} 
with $\sum\limits_{j\in J_{i}^{1}}\gamma _{i}^{j}+\sum\limits_{j\in
J_{i}^{2}}\gamma _{i}^{j}+\sum\limits_{j\in J_{i}^{3}}\gamma _{i}^{j}=1$.

Using the (\ref{eqn23}), we obtain 
\begin{equation}
\begin{array}{c}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{i\in I_{1}}\beta
_{i}\sum\limits_{j\in J_{i}^{1}}\gamma _{i}^{j}\Vert
0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert +\sum\limits_{i\in I_{1}}\beta
_{i}\sum\limits_{j\in J_{i}^{3}}\gamma _{i}^{j}\Vert 0,y-Ty,Ty-y\Vert \\
+\left[ \sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in J_{i}^{2}}\gamma
_{i}^{j}+A_{0}\right] r^{s}(F). 
\end{array}
\label{eqn26}
\end{equation} 
If $\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in J_{i}^{3}}\gamma
_{i}^{j}=1$ we have 
\begin{equation*}
\Vert 0,y-Ty,Ty-y\Vert <\Vert 0,y-Ty,Ty-y\Vert ,
\end{equation*} 
which is a contradiction.

Hence $\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in J_{i}^{3}}\gamma
_{i}^{j}<1$ and using (\ref{eqn26}), we obtain 
\begin{equation}
\begin{array}{c}
\Vert 0,y-Ty,Ty-y\Vert \leq \dfrac{\sum\limits_{i\in I_{1}}\beta
_{i}\sum\limits_{j\in J_{i}^{1}}\gamma _{i}^{j}}{1-\sum\limits_{i\in
I_{1}}\beta _{i}\sum\limits_{j\in J_{i}^{3}}\gamma _{i}^{j}}\Vert
0,y_{i}^{j}-Ty,Ty-y_{i}^{j}\Vert \\
+\dfrac{\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in J_{i}^{2}}\gamma
_{i}^{j}+A_{0}}{1-\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in
J_{i}^{3}}\gamma _{i}^{j}}r^{s}(F), 
\end{array}
\label{eqn27}
\end{equation} 
with $\dfrac{\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in
J_{i}^{1}}\gamma _{i}^{j}}{1-\sum\limits_{i\in I_{1}}\beta
_{i}\sum\limits_{j\in J_{i}^{3}}\gamma _{i}^{j}}+\dfrac{\sum\limits_{i\in
I_{1}}\beta _{i}\sum\limits_{j\in J_{i}^{2}}\gamma _{i}^{j}+A_{0}}{ 
1-\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in J_{i}^{3}}\gamma
_{i}^{j}}=1$.

Let $A_{1}=\dfrac{\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in
J_{i}^{2}}\gamma _{i}^{j}+A_{0}}{1-\sum\limits_{i\in I_{1}}\beta
_{i}\sum\limits_{j\in J_{i}^{3}}\gamma _{i}^{j}}$ and denote the index set
by $K=\underset{i\in I_{1}}{\bigcup }\left( \underset{j\in J_{i}^{1}}{ 
\bigcup }j\right) $, write $\zeta _{k}$ for $k\in K$ relative to $(i,j)$,
that is 
\begin{equation*}
\zeta _{k}=\dfrac{\sum\limits_{i\in I_{1}}\beta _{i}\sum\limits_{j\in
J_{i}^{2}}\gamma _{i}^{j}}{1-\sum\limits_{i\in I_{1}}\beta
_{i}\sum\limits_{j\in J_{i}^{3}}\gamma _{i}^{j}}\text{.}
\end{equation*} 
Also we write $y_{k}$ for $y_{i}^{j}$. Then using (\ref{eqn27}), we obtain 
\begin{equation*}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{k\in K}\zeta _{k}\Vert
0,y_{k}-Ty,Ty-y_{k}\Vert +(A_{1}+A_{0})r^{s}(F),
\end{equation*} 
with $\sum\limits_{k\in K}\zeta _{k}+A_{1}+A_{0}=1$ and $y_{k}\in F_{m-2}$.

Repeating this process we get
\begin{equation*}
\Vert 0,y-Ty,Ty-y\Vert \leq \sum\limits_{p\in P}\lambda _{p}\Vert
0,y_{p}-Ty,Ty-y_{p}\Vert +\sum\limits_{k=0}^{m-1}A_{k}r^{s}(F),
\end{equation*} 
where $y_{p}\in F_{1}$ and $\sum\limits_{p\in P}\lambda
_{p}+\sum\limits_{k=0}^{m-1}A_{k}=1$.

Then $\Vert 0,y_{p}-Ty,Ty-y_{p}\Vert \leq r^{s}(F)$ and 
\begin{equation*}
\Vert 0,y-Ty,Ty-y\Vert \leq \left( \sum\limits_{p\in P}\lambda
_{p}+\sum\limits_{k=0}^{m-1}A_{k}\right) r^{s}(F)=r^{s}(F).
\end{equation*} 
Using (\ref{eqn17}), we get 
\begin{equation*}
\Vert 0,x-Ty,Ty-x\Vert \leq \left(
\sum\limits_{k=0}^{m-1}B_{k}+\sum\limits_{p\in P}\gamma
_{p}+\sum\limits_{k=0}^{m-1}A_{k}\right) r^{s}(F),
\end{equation*} 
with $\sum\limits_{k=0}^{m-1}B_{k}+\sum\limits_{p\in P}\gamma
_{p}+\sum\limits_{k=0}^{m-1}A_{k}=1$.

Consequently, we obtain $\Vert 0,x-Ty,Ty-x\Vert \leq r^{s}(F)$ and so 
\begin{equation*}
\delta _{m+1}^{s}-\varepsilon <\Vert 0,x-Ty,Ty-x\Vert \leq r^{s}(F).
\end{equation*}

\textbf{Case 3}. For $x,y\in F_{m}$, we have 
\begin{equation}
\begin{array}{c}
\delta _{m+1}^{s}-\varepsilon <\Vert 0,Tx-Ty,Ty-Tx\Vert <\max \{\Vert
0,x-y,y-x\Vert ,\Vert 0,Tx-x,x-Tx\Vert , \\
\Vert 0,y-Ty,Ty-y\Vert ,\Vert 0,x-Ty,Ty-x\Vert ,\Vert 0,Tx-y,y-Tx\Vert \} 
\end{array}
\label{eqn28}
\end{equation} 
and repeating what has been done in \textbf{Case 2}, we get 
\begin{equation*}
\delta _{m+1}^{s}-\varepsilon <\Vert 0,Tx-Ty,Ty-Tx\Vert \leq r^{s}(F).
\end{equation*} 
In all three cases we have $\delta _{m+1}^{s}-\varepsilon <r^{s}(F)$. If $ 
\varepsilon $ tends to $0$ we get $\delta _{m+1}^{s}\leq r^{s}(F)$.

Let $F^{\infty }=\bigcup\limits_{n\in


\mathbb{N}

}F_{n}$. Then $F^{\infty }$ is nonempty because $C^{s}(F)\neq \emptyset $.
Since $F_{k}\subseteq F_{k+1}$, we obtain 
\begin{equation*}
\delta ^{s}(F^{\infty })=\lim_{k\rightarrow \infty }\delta ^{s}(F_{k})\leq
r^{s}(F).
\end{equation*} 
As $F_{k}\subset F$, $F^{\infty }\subseteq F$ and so $\delta ^{s}(F^{\infty
})\leq r^{s}(F)$.

Using the $S$-normal structure of $F$ we have $r^{s}(F)<\delta ^{s}(F)$ and $ 
\delta ^{s}(F^{\infty })<\delta ^{s}(F)$. So $F^{\infty }$ must be a proper
subset of $F$. We obtain that $F^{\infty }$ is convex and $TF^{\infty
}\subseteq F^{\infty }$.

Let $M=\overline{convF^{\infty }}=\overline{F^{\infty }}$, its diameter is
the same as $F^{\infty }$. So we have 
\begin{equation*}
\delta ^{s}(M)\leq r^{s}(F)<\delta ^{s}(F)
\end{equation*} 
and $M$ is closed, nonempty and convex proper subset of $F$. Since $T$ is
continuous then $M$ is $T$-invariant and 
\begin{equation*}
TM=TF^{\infty }\subseteq \overline{TF^{\infty }}\subseteq \overline{ 
F^{\infty }}=M.
\end{equation*} 
So $M\in \mathcal{A}$ and $M\subsetneqq F$ contradicting the minimality of $ 
F $. Hence, it should be $\delta ^{s}(F)=0$. Consequently, $F$ has a unique
fixed point under $T$.

Assume that $T$ satisfies the condition $(\mathbf{NS25})$. Using the
condition $(\mathbf{NS25})$, we have 
\begin{equation*}
\begin{array}{l}
S_{\Vert .\Vert }(Tx,Tx,Ty)=\Vert Tx-Tx,Tx-Ty,Ty-Tx\Vert =\Vert
0,Tx-Ty,Ty-Tx\Vert \\
<\max \{\Vert 0,x-y,y-x\Vert ,\Vert 0,Tx-x,x-Tx\Vert ,\Vert 0,Ty-y,y-Ty\Vert
, \\
\Vert 0,Ty-x,x-Ty\Vert ,\Vert 0,Tx-y,y-Tx\Vert \} \\
=\max \{S_{\Vert .\Vert }(x,x,y),S_{\Vert .\Vert }(Tx,Tx,x),S_{\Vert .\Vert
}(Ty,Ty,y),S_{\Vert .\Vert }(Ty,Ty,x),S_{\Vert .\Vert }(Tx,Tx,y)\} 
\end{array} 
\end{equation*} 
and so the condition $(\mathbf{S25})$ is satisfied by $T$ on $(X,S_{\Vert
.\Vert })$.

\label{prop8} Let $(X,\Vert .\Vert )$ be a Banach space, $(X,\Vert
